// Temporal Theme resolver (Lab 003, Phase 1).
//
// Pure and deterministic: given a Date and a schedule it returns the day
// phase plus the theme state that phase implies. No React, no DOM, no
// animation — the lab component owns state, CSS owns rendering.
//
// Tune the day by editing DEFAULT_SCHEDULE and PHASE_THEMES below; every
// value the page renders flows from these two tables.

export type TemporalPhase =
  | "night"
  | "dawn"
  | "morning"
  | "day"
  | "golden"
  | "sunset"
  | "dusk"
  | "evening";

export type TemporalScheme = "light" | "dark";
export type TemporalTemperature = "warm" | "neutral" | "cool";

export interface PhaseBoundary {
  phase: TemporalPhase;
  /** Local time the phase starts, as "HH:MM". */
  startsAt: string;
}

export interface TemporalState {
  phase: TemporalPhase;
  scheme: TemporalScheme;
  temperature: TemporalTemperature;
  /** 0 → 1 position inside the current phase. */
  progress: number;
  /** 0 → 1 base atmosphere strength for the phase. */
  atmosphereIntensity: number;
}

/** Phase start times in local time. Kept as strings so the day reads like a schedule. */
export const DEFAULT_SCHEDULE: PhaseBoundary[] = [
  { phase: "dawn", startsAt: "05:30" },
  { phase: "morning", startsAt: "06:30" },
  { phase: "day", startsAt: "09:00" },
  { phase: "golden", startsAt: "16:00" },
  { phase: "sunset", startsAt: "17:30" },
  { phase: "dusk", startsAt: "18:30" },
  { phase: "evening", startsAt: "19:30" },
  { phase: "night", startsAt: "22:00" },
];

/** The theme each phase implies. Scheme and temperature stay independent axes. */
export interface PhaseTheme {
  scheme: TemporalScheme;
  temperature: TemporalTemperature;
  atmosphere: number;
}

const PHASE_THEMES: Record<TemporalPhase, PhaseTheme> = {
  night: { scheme: "dark", temperature: "cool", atmosphere: 0.1 },
  dawn: { scheme: "light", temperature: "warm", atmosphere: 0.45 },
  morning: { scheme: "light", temperature: "neutral", atmosphere: 0.2 },
  day: { scheme: "light", temperature: "neutral", atmosphere: 0.05 },
  golden: { scheme: "light", temperature: "warm", atmosphere: 0.5 },
  sunset: { scheme: "light", temperature: "warm", atmosphere: 0.55 },
  dusk: { scheme: "dark", temperature: "warm", atmosphere: 0.4 },
  evening: { scheme: "dark", temperature: "neutral", atmosphere: 0.15 },
};

function toMinutes(time: string): number {
  const [hours, minutes] = time.split(":").map(Number);
  return hours * 60 + minutes;
}

/** The theme a single phase implies, without needing a time of day. */
export function phaseTheme(phase: TemporalPhase): PhaseTheme {
  return PHASE_THEMES[phase];
}

/** The whole day as data: each boundary with the theme its phase implies. */
export function describeDay(schedule: PhaseBoundary[] = DEFAULT_SCHEDULE) {
  return schedule.map((entry) => ({
    startsAt: entry.startsAt,
    phase: entry.phase,
    ...PHASE_THEMES[entry.phase],
  }));
}

export function resolveTemporalState(
  date: Date,
  schedule: PhaseBoundary[] = DEFAULT_SCHEDULE,
): TemporalState {
  const now = date.getHours() * 60 + date.getMinutes() + date.getSeconds() / 60;
  const starts = schedule.map((entry) => ({
    phase: entry.phase,
    at: toMinutes(entry.startsAt),
  }));

  // The active phase is the last boundary at or before now. Before the
  // first boundary of the day the final entry (night) still applies.
  let index = starts.length - 1;
  for (let i = 0; i < starts.length; i++) {
    if (now >= starts[i].at) index = i;
    else break;
  }
  const current = starts[index];
  const next = starts[(index + 1) % starts.length];

  let span = next.at - current.at;
  if (span <= 0) span += 24 * 60;
  let elapsed = now - current.at;
  if (elapsed < 0) elapsed += 24 * 60;

  const theme = PHASE_THEMES[current.phase];
  return {
    phase: current.phase,
    scheme: theme.scheme,
    temperature: theme.temperature,
    progress: Math.min(1, Math.max(0, elapsed / span)),
    atmosphereIntensity: theme.atmosphere,
  };
}

"use client";

import { ClockFading, Contrast, Moon, Sun } from "lucide-react";

import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
// Registry convention: intra-item imports use the @/registry path so the
// CLI rewrites them to the install targets. Nothing else changed.
import type {
  TemporalScheme,
  TemporalTemperature,
} from "@/registry/harv/temporal-theme/temporal-theme";

// The reusable seed from Lab 003: a Mindless-style compact toggle.
// Scheme flips with one tap, Dynamic follows the clock, and temperature
// lives behind the contrast button. Fully controlled — the parent owns
// every value, this owns the UI.
export function TemporalToggle({
  scheme,
  temperature,
  onSchemeChange,
  onTemperatureChange,
  dynamic = false,
  onDynamicChange,
  label = "Theme",
}: {
  scheme: TemporalScheme;
  temperature: TemporalTemperature;
  onSchemeChange: (scheme: TemporalScheme) => void;
  onTemperatureChange: (temperature: TemporalTemperature) => void;
  dynamic?: boolean;
  onDynamicChange?: (dynamic: boolean) => void;
  label?: string;
}) {
  // Warm, neutral, cool — neutral carries the scheme's own name, the
  // way the demo panel labels it, so both controls always agree.
  const temperatures: { value: TemporalTemperature; label: string }[] = [
    { value: "warm", label: "Warm" },
    { value: "neutral", label: scheme === "dark" ? "Dark" : "Light" },
    { value: "cool", label: "Cool" },
  ];
  const isDark = scheme === "dark";

  return (
    <div className="flex items-center rounded-full border bg-background/80 backdrop-blur-sm">
      <button
        type="button"
        onClick={() => onSchemeChange(isDark ? "light" : "dark")}
        aria-label={isDark ? "Switch to light mode" : "Switch to dark mode"}
        className="flex size-9 items-center justify-center rounded-full transition-colors hover:bg-foreground/10 active:scale-[0.96]"
      >
        {isDark ? (
          <Moon aria-hidden="true" className="size-[1.2rem]" />
        ) : (
          <Sun aria-hidden="true" className="size-[1.2rem]" />
        )}
      </button>
      <div aria-hidden="true" className="h-5 w-px bg-border" />
      {onDynamicChange && (
        <>
          <button
            type="button"
            onClick={() => onDynamicChange(!dynamic)}
            aria-pressed={dynamic}
            aria-label="Follow the time of day"
            title="Dynamic daylight"
            className="flex size-9 items-center justify-center rounded-full transition-colors hover:bg-foreground/10 active:scale-[0.96]"
          >
            <ClockFading
              aria-hidden="true"
              className={cn(
                "size-[1.2rem]",
                dynamic && "text-amber-500",
              )}
            />
          </button>
          <div aria-hidden="true" className="h-5 w-px bg-border" />
        </>
      )}
      <Popover>
        <PopoverTrigger asChild>
          <button
            type="button"
            aria-label={`${label} temperature settings`}
            className="flex size-9 items-center justify-center rounded-full transition-colors hover:bg-foreground/10 active:scale-[0.96]"
          >
            <Contrast
              aria-hidden="true"
              className={cn(
                "size-[1.2rem] transition-transform duration-300",
                isDark ? "rotate-180" : "rotate-0",
              )}
            />
          </button>
        </PopoverTrigger>
        <PopoverContent align="end" className="w-32 p-1">
          {temperatures.map((option) => (
            <button
              key={option.value}
              type="button"
              onClick={() => onTemperatureChange(option.value)}
              aria-pressed={temperature === option.value}
              className={cn(
                "flex w-full items-center rounded-md px-2 py-1.5 text-sm transition-colors hover:bg-foreground/10",
                temperature === option.value && "bg-accent",
              )}
            >
              {option.label}
            </button>
          ))}
        </PopoverContent>
      </Popover>
    </div>
  );
}

/* Temporal Theme demo surface (Lab 003).
 *
 * Scoped classes only — nothing here touches the global theme. The demo
 * container carries one `temporal-light*` / `temporal-dark*` class plus an
 * inline `--temporal-atmosphere` value from the resolver. Tune freely.
 */

.temporal-scope {
  --temporal-bg: #fafaf9;
  --temporal-fg: #1c1917;
  --temporal-muted: #78716c;
  --temporal-tint: transparent;
  --temporal-tint-strength: 0;
  --temporal-atmosphere: 0;

  background-color: var(--temporal-bg);
  color: var(--temporal-fg);
  transition:
    background-color 500ms ease,
    color 500ms ease;
}

.temporal-light-warm {
  --temporal-bg: #faf5ec;
  --temporal-fg: #1c1917;
  --temporal-muted: #8a7a63;
  --temporal-tint: #d97706;
  --temporal-tint-strength: 0.08;
}

.temporal-light-cool {
  --temporal-bg: #f2f6fb;
  --temporal-fg: #17202b;
  --temporal-muted: #64748b;
  --temporal-tint: #2563eb;
  --temporal-tint-strength: 0.07;
}

.temporal-dark {
  --temporal-bg: #0c0a09;
  --temporal-fg: #e7e5e4;
  --temporal-muted: #a8a29e;
}

.temporal-dark-warm {
  --temporal-bg: #14100b;
  --temporal-fg: #ede6da;
  --temporal-muted: #a89c86;
  --temporal-tint: #f59e0b;
  --temporal-tint-strength: 0.1;
}

.temporal-dark-cool {
  --temporal-bg: #0a0e14;
  --temporal-fg: #e2e8f0;
  --temporal-muted: #8fa0b3;
  --temporal-tint: #60a5fa;
  --temporal-tint-strength: 0.12;
}

/* Warm / cool wash. Strength stays low on purpose — the page should feel
 * like a room, not a filter. */
.temporal-tint {
  background-color: var(--temporal-tint);
  opacity: var(--temporal-tint-strength);
  transition: opacity 500ms ease;
}

/* The atmosphere layer. Opacity is driven by `--temporal-atmosphere`
 * (0 → 1 from the resolver); the gradient itself is deliberately quiet. */
.temporal-atmosphere {
  background:
    radial-gradient(
      120% 90% at 50% 0%,
      var(--temporal-tint) 0%,
      transparent 60%
    ),
    linear-gradient(to bottom, var(--temporal-tint), transparent 70%);
  opacity: var(--temporal-atmosphere);
  transition: opacity 600ms ease;
}

@media (prefers-reduced-motion: reduce) {
  .temporal-scope,
  .temporal-tint,
  .temporal-atmosphere {
    transition: none;
  }
}
